1	import React, { useId, useState } from 'react';
2	import { chakra, useMultiStyleConfig } from '@chakra-ui/react';
3	import { ZimmDrawer } from 'app/components/ui-kits/atoms/zimmDrawer';
4	import type { ZimmDrawerSize } from 'app/components/ui-kits/atoms/zimmDrawer';
5	import { ZimmTabs } from 'app/components/ui-kits/molecules/zimmTabs';
6	import type { ZimmTabItem } from 'app/components/ui-kits/molecules/zimmTabs';
7	
8	const ZIMM_PDP_DRAWER_RECIPE = 'ZimmPdpDrawer';
9	
10	export type ZimmPdpDrawerTab = ZimmTabItem & {
11	  content: React.ReactNode;
12	};
13	
14	type ZimmPdpDrawerProps = {
15	  isOpen: boolean;
16	  onClose: () => void;
17	  size: ZimmDrawerSize;
18	  /** SFCC-266's EU Environmental Qualities tab, SFCC-102's Size & Fit, etc. all pass their own
19	   *  content component here — this organism owns none of it (SFCC-736's scope is shell only). */
20	  tabs: ZimmPdpDrawerTab[];
21	  /** Which tab is active when the drawer mounts — e.g. the tab the triggering info-link maps to.
22	   *  Only read on first mount; pass a `key` at the call site to force a reset on reopen with a
23	   *  different starting tab. */
24	  initialTabId?: string;
25	  /** No visible title exists in the tabbed header (unlike a plain-title drawer), so this is
26	   *  required rather than filled with placeholder copy. */
27	  ariaLabel: string;
28	};
29	
30	/**
31	 * The SFCC-736 pdp/drawer deliverable — composes ZimmDrawer (shell) with ZimmTabs (nav header)
32	 * and swaps content by active tab. Renders the shell even with an empty `tabs` array (AC 11).
33	 *
34	 * @param props see ZimmPdpDrawerProps
35	 */
36	export const ZimmPdpDrawer = ({ isOpen, onClose, size, tabs, initialTabId, ariaLabel }: ZimmPdpDrawerProps) => {
37	  const styles = useMultiStyleConfig(ZIMM_PDP_DRAWER_RECIPE, { variant: size });
38	  // `initialTabId` only wins when it actually matches one of `tabs` — an id from a stale caller
39	  // or a typo would otherwise select no tab at all, and ZimmTabs gives every tab `tabIndex={-1}`
40	  // when none is active, so keyboard users could never enter the tablist.
41	  const initialTab = tabs.find((tab) => tab.id === initialTabId);
42	  const [activeTabId, setActiveTabId] = useState(initialTab?.id ?? tabs[0]?.id ?? '');
43	  // Shared with ZimmTabs (as `idPrefix`) so each tab's `id`/`aria-controls` and this panel's
44	  // `id`/`aria-labelledby` reference each other correctly — `useId()` keeps it unique even with
45	  // more than one tabbed drawer mounted at once (this page also mounts an untabbed ZimmDrawer).
46	  const idPrefix = useId();
47	
48	  const activeTab = tabs.find((tab) => tab.id === activeTabId);
49	
50	  return (
51	    <ZimmDrawer isOpen={isOpen} onClose={onClose} size={size} aria-label={ariaLabel}>
52	      {tabs.length > 0 && (
53	        <ZimmTabs
54	          tabs={tabs}
55	          activeTabId={activeTabId}
56	          onTabChange={setActiveTabId}
57	          size={size}
58	          ariaLabel={ariaLabel}
59	          idPrefix={idPrefix}
60	        />
61	      )}
62	      {activeTab ? (
63	        <chakra.div
64	          id={`${idPrefix}-panel`}
65	          role="tabpanel"
66	          aria-labelledby={`${idPrefix}-tab-${activeTabId}`}
67	          tabIndex={0}
68	          __css={styles.content}
69	        >
70	          {activeTab.content}
71	        </chakra.div>
72	      ) : (
73	        // AC 11 — zero tabs (or an activeTabId with no matching tab) still renders the shell,
74	        // but with no tab to relate a panel to, `role="tabpanel"`/`aria-labelledby` would
75	        // reference a nonexistent tab id — a plain container carries no such claim.
76	        <chakra.div __css={styles.content} />
77	      )}
78	    </ZimmDrawer>
79	  );
80	};
